from AlgorithmImports import *

class QCAlgorithmTemplate(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = []
        self.aapl_closes = []

        self.SMA_PERIOD = 20
        self.RSI_PERIOD = 14

    def OnData(self, data):
        for symbol in self.all_symbols:
            if symbol not in data:
                return

        spy_price = data[self.spy].Close
        aapl_price = data[self.aapl].Close

        self.spy_closes.append(spy_price)
        self.aapl_closes.append(aapl_price)

        if len(self.spy_closes) < self.SMA_PERIOD + 1:
            return
        if len(self.aapl_closes) < self.RSI_PERIOD + 1:
            return

        sma_current = sum(self.spy_closes[-self.SMA_PERIOD:]) / self.SMA_PERIOD
        sma_previous = sum(self.spy_closes[-self.SMA_PERIOD-1:-1]) / self.SMA_PERIOD

        rsi = self.calculate_rsi(self.aapl_closes, self.RSI_PERIOD)

        spy_shares = self.Portfolio[self.spy].Quantity
        aapl_shares = self.Portfolio[self.aapl].Quantity

        if spy_shares > 0:
            spy_current = self.spy_closes[-1]
            spy_previous = self.spy_closes[-2]

            if spy_previous >= sma_previous and spy_current < sma_current:
                self.MarketOrder(self.spy, -spy_shares)

        if aapl_shares > 0:
            if rsi > 60:
                self.MarketOrder(self.aapl, -aapl_shares)

        if spy_shares == 0:
            spy_current = self.spy_closes[-1]
            spy_previous = self.spy_closes[-2]

            if spy_previous <= sma_previous and spy_current > sma_current:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / spy_current)
                if shares_to_buy > 0:
                    self.MarketOrder(self.spy, shares_to_buy)

        if aapl_shares == 0:
            is_red_today = self.aapl_closes[-1] < self.aapl_closes[-2]
            is_red_yesterday = self.aapl_closes[-2] < self.aapl_closes[-3]
            is_red_day_before = self.aapl_closes[-3] < self.aapl_closes[-4]

            if is_red_today and is_red_yesterday and is_red_day_before:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / self.aapl_closes[-1])
                    if shares_to_buy > 0:
                        self.MarketOrder(self.aapl, shares_to_buy)

    def calculate_rsi(self, closes, period):
        gains = 0
        losses = 0

        for i in range(-period, 0):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

