class QuantConnectLeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.spy_shares = 0
        self.spy_closes = []

        self.aapl_shares = 0
        self.aapl_closes = []
        self.aapl_red_days = 0

    def OnData(self, data):
        for sym in self.symbols:
            if sym not in data or data[sym] is None:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.aapl_closes) >= 2:
            if aapl_close < self.aapl_closes[-2]:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        if len(self.spy_closes) >= 21:
            sma_today = sum(self.spy_closes[-20:]) / 20
            sma_yesterday = sum(self.spy_closes[-21:-1]) / 20
            close_today = self.spy_closes[-1]
            close_yesterday = self.spy_closes[-2]

            if self.spy_shares > 0:
                if close_yesterday >= sma_yesterday and close_today < sma_today:
                    self.Sell("SPY", self.spy_shares)
                    self.spy_shares = 0

            if self.spy_shares == 0:
                if close_yesterday <= sma_yesterday and close_today > sma_today:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    amount_to_invest = portfolio_value * 0.4
                    shares = int(amount_to_invest / close_today)
                    if shares > 0:
                        self.Buy("SPY", shares)
                        self.spy_shares = shares

        if len(self.aapl_closes) >= 15:
            rsi = self.calculate_rsi(self.aapl_closes, 14)

            if self.aapl_shares > 0:
                if rsi > 60:
                    self.Sell("AAPL", self.aapl_shares)
                    self.aapl_shares = 0

            if self.aapl_shares == 0:
                if self.aapl_red_days >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares = int(20000 / aapl_close)
                        if shares > 0:
                            self.Buy("AAPL", shares)
                            self.aapl_shares = shares

    def calculate_rsi(self, prices, period):
        if len(prices) < period + 1:
            return None

        recent = prices[-(period+1):]
        changes = [recent[i] - recent[i-1] for i in range(1, len(recent))]

        ups = sum(c for c in changes if c > 0)
        downs = sum(-c for c in changes if c < 0)

        avg_up = ups / period
        avg_down = downs / period

        if avg_down == 0:
            return 100

        rs = avg_up / avg_down
        rsi = 100 - (100 / (1 + rs))
        return rsi

