    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.strategyA_symbol = self.symbols["SPY"]
        self.strategyA_sma = SimpleMovingAverage(20)
        self.RegisterIndicator(self.strategyA_symbol, self.strategyA_sma, Resolution.Daily)

        self.strategyB_symbol = self.symbols["AAPL"]
        self.strategyB_red_days = 0
        self.strategyB_rsi = RelativeStrengthIndex(14)
        self.RegisterIndicator(self.strategyB_symbol, self.strategyB_rsi, Resolution.Daily)

        self.prev_closes = {ticker: None for ticker in self.symbols}
        self.prev_sma = None

    def OnData(self, data):
        if not all(ticker in data and data[ticker] is not None for ticker in self.symbols):
            return

        current_closes = {ticker: data[self.symbols[ticker]].Close for ticker in self.symbols}

        if self.prev_closes["AAPL"] is not None:
            if current_closes["AAPL"] < self.prev_closes["AAPL"]:
                self.strategyB_red_days += 1
            else:
                self.strategyB_red_days = 0

        if not self.strategyA_sma.IsReady or not self.strategyB_rsi.IsReady:
            self.prev_closes = current_closes.copy()
            return

        spy_close = current_closes["SPY"]
        aapl_close = current_closes["AAPL"]
        sma_value = self.strategyA_sma.Current.Value
        rsi_value = self.strategyB_rsi.Current.Value

        strategyA_shares = self.Portfolio[self.strategyA_symbol].Quantity
        if strategyA_shares > 0:
            if (self.prev_closes["SPY"] is not None and self.prev_sma is not None and
                self.prev_closes["SPY"] >= self.prev_sma and spy_close < sma_value):
                self.MarketOrder(self.strategyA_symbol, -strategyA_shares)

        if strategyA_shares == 0:
            if (self.prev_closes["SPY"] is not None and self.prev_sma is not None and
                self.prev_closes["SPY"] <= self.prev_sma and spy_close > sma_value):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.strategyA_symbol, shares_to_buy)

        strategyB_shares = self.Portfolio[self.strategyB_symbol].Quantity
        if strategyB_shares > 0:
            if rsi_value > 60:
                self.MarketOrder(self.strategyB_symbol, -strategyB_shares)

        if strategyB_shares == 0:
            if self.strategyB_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    self.MarketOrder(self.strategyB_symbol, shares_to_buy)

        self.prev_closes = current_closes.copy()
        self.prev_sma = sma_value

