from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        # Strategy A (SPY) - SMA crossover
        self.sma_spy = self.SMA("SPY", 20)
        self.prev_spy_close = None
        self.prev_sma_spy = None

        # Strategy B (AAPL) - red days and RSI
        self.rsi_aapl = self.RSI("AAPL", 14)
        self.prev_aapl_close = None
        self.aapl_red_days = 0

    def OnData(self, data):
        # Skip if any subscribed ticker is missing data
        for ticker in self.tickers:
            if not data.ContainsKey(ticker):
                return

        # Skip if indicators are not ready
        if not self.sma_spy.IsReady or not self.rsi_aapl.IsReady:
            self.prev_spy_close = data["SPY"].Close
            self.prev_aapl_close = data["AAPL"].Close
            return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close
        sma_spy = self.sma_spy.Current.Value
        rsi_aapl = self.rsi_aapl.Current.Value

        spy_qty = self.Portfolio["SPY"].Quantity
        aapl_qty = self.Portfolio["AAPL"].Quantity

        # Strategy A: SPY SMA Crossover
        # Sell on cross below
        if spy_qty > 0:
            if self.prev_spy_close is not None and self.prev_sma_spy is not None:
                if self.prev_spy_close >= self.prev_sma_spy and spy_close < sma_spy:
                    self.Liquidate("SPY")

        # Buy on cross above
        if spy_qty == 0:
            if self.prev_spy_close is not None and self.prev_sma_spy is not None:
                if self.prev_spy_close <= self.prev_sma_spy and spy_close > sma_spy:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    target_value = portfolio_value * 0.40
                    shares_to_buy = int(target_value / spy_close)
                    if shares_to_buy > 0:
                        self.Buy("SPY", shares_to_buy)

        # Strategy B: AAPL Red Days + RSI
        # Track consecutive red days
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        # Sell on RSI > 60
        if aapl_qty > 0:
            if rsi_aapl > 60:
                self.Liquidate("AAPL")

        # Buy on 3 consecutive red days
        if aapl_qty == 0:
            if self.aapl_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy("AAPL", shares_to_buy)

        # Update previous values for next bar
        self.prev_spy_close = spy_close
        self.prev_sma_spy = sma_spy
        self.prev_aapl_close = aapl_close

