        self.RegisterIndicator(self.symbols["AAPL"], self.aapl_rsi, Resolution.Daily)

        # Track previous values
        self.prev_close = {}
        self.prev_ma = None

        # Track consecutive red days for AAPL
        self.aapl_red_consecutive = 0

