        if not all(self.symbols[ticker] in data for ticker in self.tickers):
            return

        # Check if indicators are ready
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            for ticker in self.tickers:
                if ticker not in self.prev_close:
                    self.prev_close[ticker] = data[self.symbols[ticker]].Close
            return

        # Get current prices
        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        # Initialize previous values on first bar with ready indicators
        if self.prev_ma is None:
            for ticker in self.tickers:
                self.prev_close[ticker] = data[self.symbols[ticker]].Close
            self.prev_ma = self.spy_sma.Current.Value
            self.aapl_red_consecutive = 0
            return

        # Track consecutive red days
        if aapl_close < self.prev_close["AAPL"]:
            self.aapl_red_consecutive += 1
        else:
            self.aapl_red_consecutive = 0

        # Get current holdings
        spy_quantity = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_quantity = self.Portfolio[self.symbols["AAPL"]].Quantity

        # SELL FIRST
        # Strategy A sell: SPY crosses below its MA
        if spy_quantity > 0:
            if self.prev_close["SPY"] >= self.prev_ma and spy_close < self.spy_sma.Current.Value:
                self.Liquidate(self.symbols["SPY"])

        # Strategy B sell: AAPL RSI > 60
        if aapl_quantity > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate(self.symbols["AAPL"])

