        # Strategy A buy: SPY crosses above its MA
        if spy_quantity == 0:
            if self.prev_close["SPY"] <= self.prev_ma and spy_close > self.spy_sma.Current.Value:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares = int(target_value / spy_close)
                if shares > 0:
                    self.Buy(self.symbols["SPY"], shares)

        # Strategy B buy: AAPL red for 3+ days and cash available
        if aapl_quantity == 0:
            if self.aapl_red_consecutive >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.symbols["AAPL"], shares)

        # Update for next bar
        self.prev_ma = self.spy_sma.Current.Value
        for ticker in self.tickers:
            self.prev_close[ticker] = data[self.symbols[ticker]].Close

