class QuantConnectAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.price_history = {"SPY": [], "AAPL": []}

    def OnData(self, data):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close
        self.price_history["SPY"].append(spy_close)
        self.price_history["AAPL"].append(aapl_close)

        if len(self.price_history["SPY"]) < 21 or len(self.price_history["AAPL"]) < 15:
            return

        spy_ma = sum(self.price_history["SPY"][-20:]) / 20
        spy_prev_ma = sum(self.price_history["SPY"][-21:-1]) / 20
        spy_prev_close = self.price_history["SPY"][-2]

        aapl_rsi = self._compute_rsi(self.price_history["AAPL"], 14)

        spy_holdings = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_holdings = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_holdings > 0:
            if spy_prev_close >= spy_prev_ma and spy_close < spy_ma:
                self.MarketOrder(self.symbols["SPY"], -spy_holdings)
        else:
            if spy_prev_close <= spy_prev_ma and spy_close > spy_ma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_holdings > 0:
            if aapl_rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_holdings)
        else:
            aapl_prices = self.price_history["AAPL"]
            if (aapl_prices[-1] < aapl_prices[-2] and
                aapl_prices[-2] < aapl_prices[-3] and
                aapl_prices[-3] < aapl_prices[-4]):

                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

    def _compute_rsi(self, prices, period):
        if len(prices) < period + 1:
            return None

        changes = [prices[i] - prices[i-1] for i in range(1, len(prices))]
        recent_changes = changes[-period:]

        gains = sum(c for c in recent_changes if c > 0)
        losses = sum(-c for c in recent_changes if c < 0)

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

