class DualStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.closes = {symbol: [] for symbol in self.symbols}

        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_consecutive_red = 0

    def OnData(self, data):
        for symbol in self.symbols:
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        for symbol in self.symbols:
            self.closes[symbol].append(float(data[symbol].Close))

        if len(self.closes["SPY"]) < 101 or len(self.closes["AAPL"]) < 15:
            return

        spy_closes = self.closes["SPY"]
        aapl_closes = self.closes["AAPL"]

        spy_sma_prev = sum(spy_closes[-101:-1]) / 100.0
        spy_sma_curr = sum(spy_closes[-100:]) / 100.0
        spy_close_prev = spy_closes[-2]
        spy_close_curr = spy_closes[-1]

        aapl_close_prev = aapl_closes[-2]
        aapl_close_curr = aapl_closes[-1]

        if aapl_close_curr < aapl_close_prev:
            self.aapl_consecutive_red += 1
        else:
            self.aapl_consecutive_red = 0

        aapl_rsi = self.calculate_rsi(aapl_closes)

        if self.spy_lot > 0:
            if spy_close_prev >= spy_sma_prev and spy_close_curr < spy_sma_curr:
                self.MarketOrder("SPY", -self.spy_lot)
                self.spy_lot = 0

        if self.aapl_lot > 0:
            if aapl_rsi > 60:
                self.MarketOrder("AAPL", -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0:
            if spy_close_prev <= spy_sma_prev and spy_close_curr > spy_sma_curr:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / spy_close_curr)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)
                    self.spy_lot = shares_to_buy

        if self.aapl_lot == 0 and self.aapl_consecutive_red >= 3:
            if self.Portfolio.Cash >= 20000:
                shares_to_buy = int(20000 / aapl_close_curr)
                if shares_to_buy > 0:
                    self.MarketOrder("AAPL", shares_to_buy)
                    self.aapl_lot = shares_to_buy

    def calculate_rsi(self, closes):
        if len(closes) < 15:
            return None

        recent = closes[-15:]
        changes = [recent[i] - recent[i-1] for i in range(1, len(recent))]

        gains = sum(max(c, 0) for c in changes) / 14.0
        losses = sum(max(-c, 0) for c in changes) / 14.0

        if losses == 0:
            return 100.0 if gains > 0 else 0.0

        rs = gains / losses
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

