                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0
        self.aapl_prev_close = aapl_close

        # Evaluate sells before buys

        # STRATEGY A: Sell condition (SPY crosses below 100-day MA)
        if self.strategy_a_lot > 0:
            if self.spy_prev_sma is not None:
                if self.spy_prev_close >= self.spy_prev_sma and spy_close < spy_sma_value:
                    self.Liquidate(self.symbols["SPY"])
                    self.strategy_a_lot = 0

        # STRATEGY B: Sell condition (AAPL's RSI closes above 60)
        if self.strategy_b_lot > 0:
            if aapl_rsi_value > 60:
                self.Liquidate(self.symbols["AAPL"])
                self.strategy_b_lot = 0

        # STRATEGY A: Buy condition (SPY crosses above 100-day MA)
        if self.strategy_a_lot == 0:
            if self.spy_prev_sma is not None:
                if self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma_value:
                    # Invest 40% of total portfolio value in SPY
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    target_value = portfolio_value * 0.40
                    shares_to_buy = int(target_value / spy_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["SPY"], shares_to_buy)
                        self.strategy_a_lot = shares_to_buy

        # STRATEGY B: Buy condition (AAPL has been red for 3 consecutive days)
        if self.strategy_b_lot == 0:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.symbols["AAPL"], shares)
                        self.strategy_b_lot = shares

        # Update previous values for next bar's crossover detection
        self.spy_prev_close = spy_close
        self.spy_prev_sma = spy_sma_value

