import numpy as np

class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy_closes = []
        self.aapl_closes = []
        self.aapl_closes_for_rsi = []

    def OnData(self, data):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.append(spy_close)
        if len(self.spy_closes) > 101:
            self.spy_closes.pop(0)

        self.aapl_closes.append(aapl_close)
        if len(self.aapl_closes) > 4:
            self.aapl_closes.pop(0)

        self.aapl_closes_for_rsi.append(aapl_close)
        if len(self.aapl_closes_for_rsi) > 14:
            self.aapl_closes_for_rsi.pop(0)

        if len(self.spy_closes) < 101 or len(self.aapl_closes_for_rsi) < 14:
            return

        ma_today = np.mean(self.spy_closes[-100:])
        ma_yesterday = np.mean(self.spy_closes[-101:-1])
        close_today_spy = self.spy_closes[-1]
        close_yesterday_spy = self.spy_closes[-2]

        rsi_today = self.CalculateRSI(self.aapl_closes_for_rsi)

        spy_holding = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_holding = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_holding > 0:
            if close_yesterday_spy > ma_yesterday and close_today_spy <= ma_today:
                self.MarketOrder(self.symbols["SPY"], -spy_holding)

        if aapl_holding > 0:
            if rsi_today is not None and rsi_today > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_holding)

        if spy_holding == 0:
            if close_yesterday_spy <= ma_yesterday and close_today_spy > ma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment_amount = portfolio_value * 0.40
                shares_to_buy = int(investment_amount / close_today_spy)

                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_holding == 0:
            if len(self.aapl_closes) >= 4:
                c1, c2, c3, c4 = self.aapl_closes[-4:]

                if c2 < c1 and c3 < c2 and c4 < c3:
                    available_cash = self.Portfolio.Cash
                    if available_cash >= 20000:
                        shares_to_buy = int(20000 / aapl_close)

                        if shares_to_buy > 0:
                            self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

    def CalculateRSI(self, closes):
        if len(closes) < 14:
            return None

        recent_closes = closes[-14:]
        deltas = np.diff(recent_closes)

        gains = np.maximum(deltas, 0)
        losses = -np.minimum(deltas, 0)

        avg_gain = np.mean(gains)
        avg_loss = np.mean(losses)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

