                self.strategy_b_shares = 0

    def calculate_rsi(self, closes):
        if len(closes) < 14:
            return None

        recent_closes = closes[-14:]

        gains_sum = 0
        losses_sum = 0
        for i in range(1, len(recent_closes)):
            change = recent_closes[i] - recent_closes[i-1]
            if change > 0:
                gains_sum += change
            else:
                losses_sum -= change

        avg_gain = gains_sum / 14.0
        avg_loss = losses_sum / 14.0

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

