class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to the required equities
        self.symbols = {
            'SPY': self.AddEquity('SPY', Resolution.Daily).Symbol,
            'AAPL': self.AddEquity('AAPL', Resolution.Daily).Symbol,
            'IBM': self.AddEquity('IBM', Resolution.Daily).Symbol,
            'BAC': self.AddEquity('BAC', Resolution.Daily).Symbol,
            'AIG': self.AddEquity('AIG', Resolution.Daily).Symbol,
        }

        # Strategy A (SPY) - 100-day MA crossover
        self.strategy_a = {
            'sma': self.SMA(self.symbols['SPY'], 100, Resolution.Daily),
            'prev_close': None,
            'prev_sma': None,
        }

        # Strategy B (AAPL) - Red days + RSI
        self.strategy_b = {
            'rsi': self.RSI(self.symbols['AAPL'], 14, Resolution.Daily),
            'red_days_count': 0,
            'prev_close': None,
        }

    def OnData(self, data):
        # Check if all required symbols have data
        for symbol in self.symbols.values():
            if symbol not in data:
                return

        # Get current prices and positions
        spy_close = data[self.symbols['SPY']].Close
        aapl_close = data[self.symbols['AAPL']].Close
        spy_shares = self.Portfolio[self.symbols['SPY']].Quantity
        aapl_shares = self.Portfolio[self.symbols['AAPL']].Quantity

        # Strategy A - SPY
        if self.strategy_a['sma'].IsReady:
            current_sma = self.strategy_a['sma'].Current.Value

            if self.strategy_a['prev_sma'] is not None:
                prev_sma = self.strategy_a['prev_sma']
                prev_close = self.strategy_a['prev_close']

                # Sell if crosses below
                if prev_close >= prev_sma and spy_close < current_sma:
                    if spy_shares > 0:
                        self.Sell(self.symbols['SPY'], int(spy_shares))
                # Buy if crosses above
                elif prev_close <= prev_sma and spy_close > current_sma:
                    if spy_shares == 0:
                        portfolio_value = self.Portfolio.TotalPortfolioValue
                        target_value = portfolio_value * 0.40
                        shares_to_buy = int(target_value / spy_close)
                        if shares_to_buy > 0:
                            self.Buy(self.symbols['SPY'], shares_to_buy)

            self.strategy_a['prev_close'] = spy_close
            self.strategy_a['prev_sma'] = current_sma

        # Strategy B - AAPL
        # Track red days (always, not just when RSI is ready)
        if self.strategy_b['prev_close'] is not None:
            if aapl_close < self.strategy_b['prev_close']:
                self.strategy_b['red_days_count'] += 1
            else:
                self.strategy_b['red_days_count'] = 0

        self.strategy_b['prev_close'] = aapl_close

        # Only execute buy/sell if RSI is ready
        if self.strategy_b['rsi'].IsReady:
            current_rsi = self.strategy_b['rsi'].Current.Value

            # Sell if RSI > 60
            if current_rsi > 60 and aapl_shares > 0:
                self.Sell(self.symbols['AAPL'], int(aapl_shares))
            # Buy if 3 consecutive red days
            elif self.strategy_b['red_days_count'] >= 3 and aapl_shares == 0:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols['AAPL'], shares_to_buy)
